insert into news (id, slug, title_en, title_ka, excerpt_en, excerpt_ka, body_en, body_ka, sport_id, university_id, published_at, is_announcement, read_minutes, image_url) values
  ('btu-padel-cup-open', 'btu-padel-cup-registration-open', 'BTU Padel Cup registration is open', 'BTU-ს პადელის თასზე რეგისტრაცია გახსნილია', 'Eighteen of thirty-two places are already taken. Entries close on 10 November.', 'ოცდათორმეტიდან თვრამეტი ადგილი უკვე დაკავებულია. რეგისტრაცია 10 ნოემბერს იხურება.', 'BTU opens its autumn padel cup to students from every campus on the hub. The draw is mixed doubles, with a Saturday group stage across four courts and the knockout rounds on Sunday. Entry is 40 GEL per player and includes court time, balls and a shirt. Pick your university on the registration form so the organisers can seed the groups fairly.', 'BTU შემოდგომის პადელის თასს ხსნის ჰაბზე წარმოდგენილი ყველა კამპუსის სტუდენტისთვის. ბადე შერეული წყვილებისაა: შაბათს ჯგუფური ეტაპი ოთხ კორტზე, კვირას კი ნოკაუტი. მონაწილეობის საფასური მოთამაშეზე 40 ლარია და მოიცავს კორტის დროს, ბურთებს და მაისურს. რეგისტრაციისას მიუთითე შენი უნივერსიტეტი, რომ ორგანიზატორებმა ჯგუფები სამართლიანად დათესონ.', 'padel', 'btu', '2026-10-22T10:00:00+04:00', true, 2, null),
  ('new-padel-courts', 'two-new-padel-courts-open-at-saburtalo', 'Two new padel courts open at Saburtalo', 'საბურთალოზე ორი ახალი პადელის კორტი გაიხსნა', 'Weekday mornings are free for students with a university ID from November.', 'ნოემბრიდან სამუშაო დღეების დილის საათები უფასოა სტუდენტური ბარათის მქონეთათვის.', 'Padel Park Saburtalo has added two covered courts, taking the venue to six. Free weekday morning slots between 08:00 and 12:00 have been agreed for students holding a university ID, bookable through each campus sports office. The extra capacity is what allows the BTU cup to run four courts in parallel next month.', 'პადელ პარკ საბურთალოს დაემატა ორი დახურული კორტი და ობიექტზე ჯამში ექვსი გახდა. სამუშაო დღეებში 08:00-დან 12:00-მდე უფასო სლოტები შეთანხმდა სტუდენტური ბარათის მქონე სტუდენტებისთვის, დაჯავშნა კი თითოეული კამპუსის სპორტის ოფისის მეშვეობითაა შესაძლებელი. სწორედ დამატებული სიმძლავრე იძლევა იმის საშუალებას, რომ BTU-ს თასმა მომავალ თვეში ოთხი კორტი პარალელურად გამოიყენოს.', 'padel', null, '2026-10-20T09:00:00+04:00', true, 3, null),
  ('hub-expansion', 'two-more-universities-join-the-hub', 'BTU is first — more universities to follow', 'BTU პირველია — სხვა უნივერსიტეტებიც შემოგვიერთდებიან', 'The hub launches with BTU. Other campuses join as soon as their federations sign up.', 'ჰაბი BTU-თი იწყებს. სხვა კამპუსები შემოუერთდებიან, როგორც კი მათი ფედერაციები დაადასტურებენ.', 'The hub opens with the Business and Technology University, whose football federation publishes its league, groups, All-Star XI and champions here. Each campus keeps control of what it publishes — its own tournaments, its own registration deadlines, its own announcements — and students filter the site down to whichever universities they care about. Talks with other federations are under way.', 'ჰაბი იხსნება ბიზნესისა და ტექნოლოგიების უნივერსიტეტით, რომლის ფეხბურთის ფედერაციაც აქ აქვეყნებს თავის ლიგას, ჯგუფებს, ALLSTAR შემადგენლობასა და ჩემპიონებს. თითოეული კამპუსი თავად აკონტროლებს, რას აქვეყნებს — საკუთარ ტურნირებს, საკუთარ ვადებს, საკუთარ განცხადებებს — სტუდენტები კი საიტს იმ უნივერსიტეტებზე ფილტრავენ, რომლებიც მათ აინტერესებთ. სხვა ფედერაციებთან მოლაპარაკებები მიმდინარეობს.', null, null, '2026-10-14T11:00:00+04:00', true, 2, null)
on conflict (id) do update set
  slug = excluded.slug,
  title_en = excluded.title_en,
